class Allergies:
    ALLERGENS = [
        ("eggs", 1),
        ("peanuts", 2),
        ("shellfish", 4),
        ("strawberries", 8),
        ("tomatoes", 16),
        ("chocolate", 32),
        ("pollen", 64),
        ("cats", 128),
    ]

    def __init__(self, score):
        # keep only the lower 8 bits that correspond to known allergens
        try:
            self.score = int(score) & 0xFF
        except (TypeError, ValueError):
            # if score cannot be converted to int, treat as 0
            self.score = 0

    def allergic_to(self, item):
        if not isinstance(item, str):
            return False
        item = item.lower()
        for name, value in self.ALLERGENS:
            if name == item:
                return bool(self.score & value)
        return False

    @property
    def lst(self):
        return [name for name, value in self.ALLERGENS if self.score & value]
